import json
import re
import logging
from pathlib import Path
from typing import List, Dict, Any, Optional, Tuple
from config.settings import get_paths, ensure_directories
from src.detection.schema import LLMCodeDetectionResult, ConfidenceLevel

logger = logging.getLogger(__name__)

# Heuristic patterns for LLM-generated code
# These patterns look for common artifacts found in LLM outputs:
# 1. Excessive markdown code fencing within diffs (though diffs usually strip this, sometimes they remain)
# 2. Specific comment patterns often generated by LLMs (e.g., "Here is the fix", "Refactored by AI")
# 3. Unusual whitespace or indentation patterns specific to certain model outputs
# 4. Comments explicitly mentioning AI/LLM tools
# 5. Generic, verbose explanatory comments inserted directly into code blocks

LLM_SIGNATURE_PATTERNS = [
    r'(?i)generated\s+by\s+(?:ai|llm|large\s+language\s+model)',
    r'(?i)here\s+is\s+the\s+code',
    r'(?i)here\s+is\s+the\s+fix',
    r'(?i)refactored\s+by\s+ai',
    r'(?i)ai\s+generated',
    r'(?i)llm\s+generated',
    r'(?i)automatically\s+generated\s+by',
    r'(?i)code\s+generated\s+by\s+llm',
    r'(?i)assistant:',
    r'(?i)user:\s*\n\s*code:',
    r'(?i)think\s+step\s+by\s+step',
    r'(?i)ensure\s+that\s+you\s+follow',
    r'(?i)as\s+an\s+ai\s+language\s+model',
    r'(?i)I\s+cannot\s+do\s+that',
    r'(?i)here\s+is\s+a\s+snippet',
    r'(?i)snippet\s+below',
    # Common verbose comment styles often seen in LLM outputs
    r'(?i)#\s+this\s+function\s+is\s+designed\s+to',
    r'(?i)#\s+this\s+method\s+handles',
    r'(?i)#\s+note:\s+this\s+was\s+generated',
]

# Thresholds for heuristic scoring
# A diff is flagged if it contains at least one strong signature or multiple weak ones
STRONG_SIGNATURE_THRESHOLD = 1
WEAK_SIGNATURE_THRESHOLD = 3

def calculate_confidence(score: float, total_lines: int) -> ConfidenceLevel:
    """
    Calculate confidence level based on heuristic score and total lines.
    
    Args:
        score: The calculated heuristic score
        total_lines: Total number of lines in the diff content
        
    Returns:
        ConfidenceLevel enum value
    """
    if total_lines == 0:
        return ConfidenceLevel.UNSURE
    
    ratio = score / max(total_lines, 1)
    
    if ratio >= 0.1 or score >= STRONG_SIGNATURE_THRESHOLD:
        return ConfidenceLevel.HIGH
    elif ratio >= 0.05 or score >= WEAK_SIGNATURE_THRESHOLD:
        return ConfidenceLevel.MEDIUM
    elif score > 0:
        return ConfidenceLevel.LOW
    else:
        return ConfidenceLevel.UNSURE

def detect_llm_generated_code(diff_content: str, pr_id: str, file_path: str) -> LLMCodeDetectionResult:
    """
    Detect LLM-generated code in a diff using heuristic patterns.
    
    Args:
        diff_content: The raw diff content string
        pr_id: The PR identifier
        file_path: The file path being diffed
        
    Returns:
        LLMCodeDetectionResult object with detection details
    """
    if not diff_content:
        return LLMCodeDetectionResult(
            pr_id=pr_id,
            file_path=file_path,
            llm_code_flag=False,
            confidence=ConfidenceLevel.UNSURE,
            detection_reason="Empty diff content",
            heuristic_score=0.0,
            matched_patterns=[]
        )
    
    lines = diff_content.split('\n')
    total_lines = len(lines)
    matched_patterns = []
    heuristic_score = 0.0
    
    # Check each line for LLM signatures
    for line in lines:
        for pattern in LLM_SIGNATURE_PATTERNS:
            if re.search(pattern, line):
                matched_patterns.append(pattern)
                heuristic_score += 1.0
                break  # Count each line only once even if multiple patterns match
    
    confidence = calculate_confidence(heuristic_score, total_lines)
    llm_code_flag = confidence in [ConfidenceLevel.HIGH, ConfidenceLevel.MEDIUM]
    
    reason = "No LLM signatures detected"
    if matched_patterns:
        reason = f"Detected {len(matched_patterns)} LLM signature pattern(s)"
        
    return LLMCodeDetectionResult(
        pr_id=pr_id,
        file_path=file_path,
        llm_code_flag=llm_code_flag,
        confidence=confidence,
        detection_reason=reason,
        heuristic_score=heuristic_score,
        matched_patterns=matched_patterns
    )

def process_pr_diffs(input_file: Path, output_file: Path) -> List[Dict[str, Any]]:
    """
    Process PR diffs from an input JSON file and detect LLM-generated code.
    
    Args:
        input_file: Path to the input JSON file containing PR data
        output_file: Path to the output JSON file for detection results
        
    Returns:
        List of detection results as dictionaries
    """
    if not input_file.exists():
        raise FileNotFoundError(f"Input file not found: {input_file}")
    
    logger.info(f"Reading PR data from {input_file}")
    with open(input_file, 'r', encoding='utf-8') as f:
        pr_data = json.load(f)
    
    results = []
    
    for pr_item in pr_data:
        pr_id = pr_item.get('pr_id', 'unknown')
        
        if 'files' not in pr_item or not isinstance(pr_item['files'], list):
            logger.warning(f"PR {pr_id} has no files or invalid files structure, skipping")
            continue
        
        for file_item in pr_item['files']:
            file_path = file_item.get('file_path', 'unknown')
            diff_content = file_item.get('diff', '')
            
            if not diff_content:
                logger.debug(f"PR {pr_id}, file {file_path}: No diff content, skipping")
                continue
            
            detection_result = detect_llm_generated_code(
                diff_content=diff_content,
                pr_id=pr_id,
                file_path=file_path
            )
            
            result_dict = detection_result.to_dict()
            results.append(result_dict)
            
            if detection_result.llm_code_flag:
                logger.info(f"PR {pr_id}, file {file_path}: LLM code detected ({detection_result.confidence.value})")
            else:
                logger.debug(f"PR {pr_id}, file {file_path}: No LLM code detected")
    
    # Ensure output directory exists
    ensure_directories([output_file.parent])
    
    logger.info(f"Writing {len(results)} detection results to {output_file}")
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
    
    return results

def main():
    """Main entry point for the LLM code detection pipeline."""
    paths = get_paths()
    input_file = paths['raw_prs'] / 'processed_prs.json'
    output_file = paths['derived'] / 'llm_detections.json'
    
    # Ensure input file exists
    if not input_file.exists():
        logger.error(f"Input file not found: {input_file}")
        logger.error("Please run the extraction pipeline first to generate processed_prs.json")
        raise FileNotFoundError(f"Input file not found: {input_file}")
    
    try:
        results = process_pr_diffs(input_file, output_file)
        logger.info(f"Successfully processed {len(results)} file diffs")
        
        # Summary statistics
        flagged_count = sum(1 for r in results if r['llm_code_flag'])
        logger.info(f"Flagged {flagged_count} files as potentially LLM-generated")
        
    except Exception as e:
        logger.error(f"Error processing PR diffs: {e}", exc_info=True)
        raise

if __name__ == '__main__':
    main()
